def skill():
    m = Rational(30, 2)
    tbl = {1.0: Rational('0.3413'), 1.5: Rational('0.4332'), 2.0: Rational('0.4772'), 2.5: Rational('0.4938')}
    z = [k for k, v in tbl.items() if v == Rational('0.4332')][0]
    sigma = (m - 9) / Rational(str(z))
    return m + sigma

def standard():
    tbl = {1.0: Rational('0.3413'), 1.5: Rational('0.4332'), 2.0: Rational('0.4772'), 2.5: Rational('0.4938')}
    x = Symbol('x')
    m, s = symbols('m s')
    # 대칭 조건: x - m = -(30 - x - m)  (모든 x)
    m0 = solve(Eq(x - m, -(30 - x - m)), m)[0]
    cand = []
    for k, v in tbl.items():
        if v == Rational('0.4332'):
            cand.append(m0 + (m0 - 9) / Rational(str(k)))
    assert len(cand) == 1
    return cand[0]

def unique():
    return [standard()]
